<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue'
const lane=ref(1), score=ref(0), status=ref('ready'), obstacles=ref([])
let timer, ticker, id=0
function move(n){ lane.value=Math.max(0,Math.min(2,lane.value+n)) }
function start(){score.value=0;lane.value=1;obstacles.value=[];status.value='playing'; clearInterval(timer);clearInterval(ticker);timer=setInterval(()=>{if(status.value==='playing') obstacles.value.push({id:id++,lane:Math.floor(Math.random()*3),x:100})},1050);ticker=setInterval(()=>{if(status.value!=='playing')return;obstacles.value.forEach(o=>o.x-=1.2);for(const o of obstacles.value){if(o.x<12&&o.x>7&&o.lane===lane.value){status.value='lost';clearInterval(timer);clearInterval(ticker)}}const passed=obstacles.value.filter(o=>o.x<0);score.value+=passed.length;obstacles.value=obstacles.value.filter(o=>o.x>=0);if(score.value>=17){status.value='won';clearInterval(timer);clearInterval(ticker)}},30)}
function key(e){if(['ArrowUp','w','W'].includes(e.key)){e.preventDefault();move(-1)} if(['ArrowDown','s','S'].includes(e.key)){e.preventDefault();move(1)} if(e.key==='Enter'&&status.value!=='playing')start()}
onMounted(()=>window.addEventListener('keydown',key));onBeforeUnmount(()=>{window.removeEventListener('keydown',key);clearInterval(timer);clearInterval(ticker)})
</script>
<template><main class="game"><div class="stars"></div><NuxtLink class="game-back" to="/">← BACK TO THE STORY</NuxtLink><div class="game-brand">✳<small>ORBIT STUDIO</small></div><div class="game-title">A LITTLE DETOUR<br><small>DODGE THE IDEAS THAT GOT AWAY</small></div><div class="lanes"><div v-for="i in 3" :key="i" class="lane"></div><div class="game-ship" :style="{top:`${lane*33.33+16.6}%`}">➤</div><div v-for="o in obstacles" :key="o.id" class="asteroid" :style="{left:o.x+'%',top:`${o.lane*33.33+16.6}%`}">✹</div></div><div class="game-controls"><span>FLIGHT CONTROLS</span><button @click="move(-1)" aria-label="Move up">↑</button><button @click="move(1)" aria-label="Move down">↓</button><small>OR USE ↑ ↓ / W S</small></div><div class="game-score">ORBITS COMPLETE<br><strong>{{ String(score).padStart(2,'0') }} / 17</strong></div><div v-if="status!=='playing'" class="game-modal"><span>✳</span><h1>{{status==='ready'?'READY FOR TAKEOFF?':status==='won'?'NICE JOURNEY!':'LOST IN SPACE?'}}</h1><p>{{status==='ready'?'Move between lanes and dodge the obstacles.':status==='won'?'You made it around the sun.':'Every great idea takes a few tries.'}}</p><button @click="start">{{status==='ready'?'LET’S GO':'TRY AGAIN'}} ↗</button><small>PRESS ENTER</small></div></main></template>
